public static void main(Args _args)
{
    MZNAG_PurchaseOrderControlledDocumentController controller = new MZNAG_PurchaseOrderControlledDocumentController();
    controller.parmArgs(_args);
    controller.parmReportName(ssrsReportStr(MZNAG_PurchaseOrderControlledDocumentReport, Report));
    controller.parmShowDialog(false);
    controller.startOperation();
}

protected void preRunModifyContract()
{
    Query                 q;
    QueryBuildRange       qbr;
    QueryBuildDataSource  qbds;
    RecId                 recId;
    VendPurchOrderJour    VPJ;

    if (this.parmArgs() && this.parmArgs().record())
    {
        VPJ   = this.parmArgs().record();
        recId = VPJ.RecId;
    }

    q = this.getFirstQuery();

    if (q)
    {
        qbds = q.dataSourceTable(tableNum(VendPurchOrderJour));

        if (qbds && recId)
        {
            // Clears duplicate ranges and sets the targeted record's RecId range
            qbr = SysQuery::findOrCreateRange(qbds, fieldNum(VendPurchOrderJour, RecId));
            qbr.value(queryValue(recId));
        }
    }
}

public void setRanges(Query _query)
{
    QueryBuildDataSource  queryBuildDataSource;
    str                   range;
    VendPurchOrderJour    VPJ;

    if (this.parmArgs() && this.parmArgs().record() && _query)
    {
        VPJ = this.parmArgs().record();
        queryBuildDataSource = _query.dataSourceTable(tableNum(VendPurchOrderJour));

        if (queryBuildDataSource)
        {
            queryBuildDataSource.clearRanges();
            range = queryValue(VPJ.RecId);

            SysQuery::findOrCreateRange(queryBuildDataSource, fieldNum(VendPurchOrderJour, RecId)).value(range);
        }
    }
}
